public int findPeakElement(int[] nums) {
    int left = 0, right = nums.length - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;  // 防溢出写法

        if (nums[mid] < nums[mid + 1]) {
            // 上升趋势：右侧必有峰值，排除 mid（mid 不可能是峰）
            left = mid + 1;
        } else {
            // 下降趋势：左侧含 mid 可能有峰，保留 mid
            right = mid;
        }
    }

    return left;  // left == right，即峰值索引
}

public int findPeakElementLinear(int[] nums) {
    for (int i = 0; i < nums.length - 1; i++) {
        if (nums[i] > nums[i + 1]) {
            return i;  // 第一个下降点即峰值
        }
    }
    return nums.length - 1;  // 单调递增，最后一个元素是峰值
}
